#define WS2812_TEST_NLEDS 16

/* Pixel format is the driver's: 0x00RRGGBB in host byte ordering. */

#define WS2812_TEST_RED   0x00ff0000u
#define WS2812_TEST_GREEN 0x0000ff00u
