      fprintf(stderr, "ws2812_test: write failed: %d\n", errno);
      return -1;
    }

  if ((size_t)nwritten != frame_len)
    {
      fprintf(stderr, "ws2812_test: short write: %ld of %zu\n", (long)nwritten,
              frame_len);
